CREATE TABLE IF NOT EXISTS reach_sum (video_id TEXT PRIMARY KEY, imp REAL DEFAULT 0, clk REAL DEFAULT 0, imp24 REAL DEFAULT 0, clk24 REAL DEFAULT 0); CREATE INDEX IF NOT EXISTS reach_day ON reach (day); INSERT OR IGNORE INTO kv (key, value) SELECT 'reach_since', MIN(day) FROM reach HAVING COUNT(*) > 0; DELETE FROM snapshots WHERE length(ts) > 10 AND EXISTS (SELECT 1 FROM videos v WHERE v.id = snapshots.video_id AND snapshots.ts > strftime('%Y-%m-%dT%H', v.published, '+53 hours')); DELETE FROM reach WHERE video_id IN (SELECT id FROM videos WHERE is_short = 1); DELETE FROM kv WHERE key IN ('cache_thumbs','cache_grades','cache_comp');
